const db = createClient({ url: process.env.DATABASE_URL || "file:central-precatorios.db", authToken: process.env.DATABASE_AUTH_TOKEN });
export const acquisitionJobStates = ["DISCOVERED","FILTERING","ELIGIBILITY_CHECK","INVESTIGATING","RESOLVING_CREDITOR","COLLECTING_EVIDENCE","COLLECTING_CONTACT","CROSS_CHECKING","QUALIFIED_WITH_PENDING","READY_FOR_ANALYST","REJECTED","SOURCE_BLOCKED","WAITING","ERROR","PAUSED"] as const;
export type AcquisitionJobState = typeof acquisitionJobStates[number];
export const officialEvidenceTypes = ["OFICIO_REQUISITORIO","OFICIO_COMPLEMENTAR","REQUISITORIO","PROCESS_DOCUMENT","OFFICIAL_RECORD","OTHER_OFFICIAL_DOCUMENT"] as const;
const jobSelect = `SELECT j.*,o.title,o.debtor,o.tribunal,o.process,o.nominal,o.workflow,o.source FROM autonomous_acquisition_jobs j JOIN operations o ON o.id=j.operation_id AND o.organization_id=j.organization_id`;

export type OfficialEvidenceDocument = { id:string;organizationId:string;operationId:string;documentType:typeof officialEvidenceTypes[number];title:string;source:string;sourceUrl:string;downloadUrl:string;documentIdentifier:string;reference:string;publishedAt:string;collectedAt:string;page:number|null;hash:string;contentFingerprint:string;status:"COLLECTED"|"VERIFIED"|"DIVERGENT"|"FAILED";evidenceStrength:"STRONG"|"MEDIUM"|"WEAK";notes:string;sourceProvenance:OfficialEvidenceSourceProvenance|null };
export type OfficialEvidenceSourceProvenance = { provider:string;sourceId:string;route:string };
export type AcquisitionContact = { id:string;organizationId:string;operationId:string;type:"PHONE"|"MOBILE"|"EMAIL"|"WEBSITE"|"OTHER";value:string;source:string;sourceUrl:string;collectedAt:string;confidence:number;notes:string };
export type AcquisitionJob = { id:string;organizationId:string;operationId:string;operationVersion:number;importBatchId:string;status:AcquisitionJobState;currentStep:string;attempts:number;maxAttempts:number;startedAt:string;finishedAt:string;nextRunAt:string;durationMs:number;lastError:string;workerId:string;priority:number;createdAt:string;updatedAt:string;reasons:string[];summary:Record<string,unknown> };

export async function initializeAutonomousAcquisition(client:Client=db){
 await client.execute(`CREATE TABLE IF NOT EXISTS autonomous_acquisition_jobs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation_id TEXT NOT NULL,operation_version INTEGER NOT NULL,import_batch_id TEXT NOT NULL,status TEXT NOT NULL,current_step TEXT NOT NULL,attempts INTEGER NOT NULL,max_attempts INTEGER NOT NULL,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,next_run_at TEXT NOT NULL,duration_ms INTEGER NOT NULL,last_error TEXT NOT NULL,worker_id TEXT NOT NULL,priority REAL NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,reasons_json TEXT NOT NULL,summary_json TEXT NOT NULL)`);
 await client.execute("CREATE UNIQUE INDEX IF NOT EXISTS acquisition_job_version_idx ON autonomous_acquisition_jobs(organization_id,operation_id,operation_version)");
 await client.execute("CREATE INDEX IF NOT EXISTS acquisition_job_queue_idx ON autonomous_acquisition_jobs(organization_id,status,next_run_at,priority DESC,created_at)");
 await client.execute(`CREATE TABLE IF NOT EXISTS acquisition_events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation_id TEXT NOT NULL,job_id TEXT NOT NULL,source_id TEXT NOT NULL,event_type TEXT NOT NULL,status TEXT NOT NULL,query_identifier TEXT NOT NULL,source_url TEXT NOT NULL,query_id TEXT NOT NULL,consulted_at TEXT NOT NULL,source_reference_date TEXT NOT NULL,http_status INTEGER,document_id TEXT NOT NULL,evidence_reference TEXT NOT NULL,access_result TEXT NOT NULL,failure_reason TEXT NOT NULL,details_json TEXT NOT NULL,idempotency_key TEXT NOT NULL)`);
 await client.execute("CREATE UNIQUE INDEX IF NOT EXISTS acquisition_event_idempotency_idx ON acquisition_events(organization_id,job_id,idempotency_key)");
 await client.execute("CREATE INDEX IF NOT EXISTS acquisition_event_timeline_idx ON acquisition_events(organization_id,operation_id,consulted_at DESC)");
 await client.execute(`CREATE TABLE IF NOT EXISTS official_evidence_documents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation_id TEXT NOT NULL,document_type TEXT NOT NULL,title TEXT NOT NULL,source TEXT NOT NULL,source_url TEXT NOT NULL,download_url TEXT NOT NULL,document_identifier TEXT NOT NULL,reference TEXT NOT NULL,published_at TEXT NOT NULL,collected_at TEXT NOT NULL,page INTEGER,hash TEXT NOT NULL,content_fingerprint TEXT NOT NULL,status TEXT NOT NULL,evidence_strength TEXT NOT NULL,notes TEXT NOT NULL,idempotency_key TEXT NOT NULL,source_provenance_json TEXT NOT NULL DEFAULT '{}')`);
 const evidenceColumns=await client.execute("PRAGMA table_info(official_evidence_documents)");if(!evidenceColumns.rows.some(row=>String(row.name)==="source_provenance_json"))await client.execute("ALTER TABLE official_evidence_documents ADD COLUMN source_provenance_json TEXT NOT NULL DEFAULT '{}'");
 await client.execute("CREATE UNIQUE INDEX IF NOT EXISTS official_evidence_idempotency_idx ON official_evidence_documents(organization_id,operation_id,idempotency_key)");
 await client.execute("CREATE INDEX IF NOT EXISTS official_evidence_case_idx ON official_evidence_documents(organization_id,operation_id,status,document_type)");
 await client.execute(`CREATE TABLE IF NOT EXISTS acquisition_contacts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation_id TEXT NOT NULL,type TEXT NOT NULL,value TEXT NOT NULL,source TEXT NOT NULL,source_url TEXT NOT NULL,collected_at TEXT NOT NULL,confidence REAL NOT NULL,notes TEXT NOT NULL,idempotency_key TEXT NOT NULL)`);
 await client.execute("CREATE UNIQUE INDEX IF NOT EXISTS acquisition_contact_idempotency_idx ON acquisition_contacts(organization_id,operation_id,idempotency_key)");
 await client.execute(`CREATE TABLE IF NOT EXISTS acquisition_source_cache(source_id TEXT NOT NULL,query_hash TEXT NOT NULL,status TEXT NOT NULL,result_count INTEGER NOT NULL,http_status INTEGER,source_url TEXT NOT NULL,query_id TEXT NOT NULL,consulted_at TEXT NOT NULL,expires_at TEXT NOT NULL,failure_reason TEXT NOT NULL,PRIMARY KEY(source_id,query_hash))`);
 await client.execute(`CREATE TABLE IF NOT EXISTS notification_channels(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,channel TEXT NOT NULL,enabled INTEGER NOT NULL,config_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,channel))`);
 await client.execute(`CREATE TABLE IF NOT EXISTS notification_deliveries(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation_id TEXT NOT NULL,job_id TEXT NOT NULL,channel TEXT NOT NULL,qualification_key TEXT NOT NULL,status TEXT NOT NULL,scheduled_at TEXT NOT NULL,delivered_at TEXT NOT NULL,attempts INTEGER NOT NULL,last_error TEXT NOT NULL,summary_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,operation_id,qualification_key,channel))`);
 await client.execute("CREATE INDEX IF NOT EXISTS notification_delivery_schedule_idx ON notification_deliveries(organization_id,status,scheduled_at)");
}

function jsonObject(value:unknown):Record<string,unknown>{try{return JSON.parse(String(value||"{}")) as Record<string,unknown>}catch{return{}}}
function rowJob(row:Record<string,unknown>):AcquisitionJob{return{id:String(row.id),organizationId:String(row.organization_id),operationId:String(row.operation_id),operationVersion:Number(row.operation_version),importBatchId:String(row.import_batch_id),status:String(row.status) as AcquisitionJobState,currentStep:String(row.current_step),attempts:Number(row.attempts),maxAttempts:Number(row.max_attempts),startedAt:String(row.started_at),finishedAt:String(row.finished_at),nextRunAt:String(row.next_run_at),durationMs:Number(row.duration_ms),lastError:String(row.last_error),workerId:String(row.worker_id),priority:Number(row.priority),createdAt:String(row.created_at),updatedAt:String(row.updated_at),reasons:JSON.parse(String(row.reasons_json||"[]")) as string[],summary:jsonObject(row.summary_json)}}
function rowOfficialEvidence(row:Record<string,unknown>):OfficialEvidenceDocument{return{id:String(row.id),organizationId:String(row.organization_id),operationId:String(row.operation_id),documentType:String(row.document_type) as OfficialEvidenceDocument["documentType"],title:String(row.title),source:String(row.source),sourceUrl:String(row.source_url),downloadUrl:String(row.download_url),documentIdentifier:String(row.document_identifier),reference:String(row.reference),publishedAt:String(row.published_at),collectedAt:String(row.collected_at),page:row.page===null?null:Number(row.page),hash:String(row.hash),contentFingerprint:String(row.content_fingerprint),status:String(row.status) as OfficialEvidenceDocument["status"],evidenceStrength:String(row.evidence_strength) as OfficialEvidenceDocument["evidenceStrength"],notes:String(row.notes),sourceProvenance:parseEvidenceProvenance(row.source_provenance_json)}}
function parseEvidenceProvenance(value:unknown):OfficialEvidenceSourceProvenance|null{const parsed=jsonObject(value);if(!parsed||typeof parsed!=="object"||Array.isArray(parsed))return null;const provider=String(parsed.provider||"").trim(),sourceId=String(parsed.sourceId||"").trim(),route=String(parsed.route||"").trim();return provider&&sourceId&&route?{provider,sourceId,route}:null}
function rowContact(row:Record<string,unknown>):AcquisitionContact{return{id:String(row.id),organizationId:String(row.organization_id),operationId:String(row.operation_id),type:String(row.type) as AcquisitionContact["type"],value:String(row.value),source:String(row.source),sourceUrl:String(row.source_url),collectedAt:String(row.collected_at),confidence:Number(row.confidence),notes:String(row.notes)}}

export async function enqueueImportedBatch(batchId:string,organizationId:string,actorUserId:string,client:Client=db){
 await initializeAutonomousAcquisition(client);
 const rows=await client.execute({sql:"SELECT DISTINCT o.id,o.version,o.nominal,o.workflow FROM capture_import_rows r JOIN operations o ON o.id=r.operation_id AND o.organization_id=r.organization_id WHERE r.organization_id=? AND r.batch_id=? AND o.is_demo=0",args:[organizationId,batchId]});
 const now=new Date().toISOString();
 const statements=rows.rows.map(row=>{const workflow=jsonObject(row.workflow),credit=jsonObject(workflow.credit),priority=Math.min(1000,Number(row.nominal||0)/1000)+(credit.numeroProcessoDEPRE?100:0)+(credit.originProcessNumber?25:0);return{sql:"INSERT OR IGNORE INTO autonomous_acquisition_jobs VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",args:[crypto.randomUUID(),organizationId,String(row.id),Number(row.version),batchId,"DISCOVERED","DISCOVERED",0,10,"","","",0,"","",priority,now,now,"[]","{}"]}});
 const inserted=statements.length?await client.batch(statements,"write"):[];
 await client.execute({sql:"INSERT OR IGNORE INTO notification_channels(id,organization_id,channel,enabled,config_json,created_at,updated_at) VALUES(?,?,?,0,?,?,?)",args:[crypto.randomUUID(),organizationId,"TELEGRAM",JSON.stringify({alertsPerBusinessDay:3,timezone:"America/Sao_Paulo",slots:["09:00","12:00","15:00"]}),now,now]});
 return{enqueued:inserted.reduce((sum,result)=>sum+result.rowsAffected,0),actorUserId};
}

export type DocumentaryQualificationInput = Pick<OfficialEvidenceDocument, "sourceUrl" | "documentType" | "status" | "evidenceStrength" | "documentIdentifier" | "reference" | "hash">;
export type DocumentaryQualificationAudit = { qualifies: boolean; reasons: string[]; identity: string | null };
export function auditDocumentaryQualification<T extends DocumentaryQualificationInput>(document: T): DocumentaryQualificationAudit {
 const reasons: string[] = [];
 const qualifyingTypes = new Set<typeof officialEvidenceTypes[number]>(["OFICIO_REQUISITORIO", "OFICIO_COMPLEMENTAR"]);
 if (!isOfficialUrl(document.sourceUrl)) reasons.push("OFFICIAL_URL_REQUIRED");
 if (!qualifyingTypes.has(document.documentType)) reasons.push("DOCUMENT_TYPE_NOT_QUALIFYING");
 if (document.status !== "VERIFIED") reasons.push("STATUS_NOT_VERIFIED");
 if (document.evidenceStrength !== "STRONG") reasons.push("STRENGTH_NOT_STRONG");
 const identifier = document.documentIdentifier.trim(), reference = document.reference.trim();
 if (!identifier && !reference) reasons.push("IDENTIFIER_OR_REFERENCE_REQUIRED");
 const identity = document.hash ? `hash:${document.hash.toLowerCase()}` : identifier ? `document:${identifier.toLowerCase()}` : reference ? `reference:${document.documentType}|${document.sourceUrl}|${reference.toLowerCase()}` : null;
 return { qualifies: reasons.length === 0, reasons, identity };
}
export function countVerifiedOfficialEvidence<T extends DocumentaryQualificationInput>(documents:readonly T[]){const identities=new Set<string>();for(const document of documents){const audit=auditDocumentaryQualification(document);if(audit.qualifies&&audit.identity)identities.add(audit.identity)}return identities.size}
function isOfficialUrl(value:string){return isOfficialSourceUrl(value)}

const evidenceSourceProvenanceSchema=z.object({provider:z.string().trim().min(1).max(120),sourceId:z.string().trim().min(1).max(160),route:z.string().trim().min(1).max(240)}).strict();
const officialEvidenceInput=z.object({operationId:z.string().uuid(),documentType:z.enum(officialEvidenceTypes),title:z.string().trim().min(1).max(240),source:z.string().trim().min(1).max(160),sourceUrl:z.string().url().max(1000),downloadUrl:z.string().url().max(1000).or(z.literal("")).default(""),documentIdentifier:z.string().trim().max(240).default(""),reference:z.string().trim().max(500).default(""),publishedAt:z.union([z.literal(""),z.iso.date()]).default(""),page:z.number().int().positive().nullable().default(null),hash:z.string().regex(/^[a-f0-9]{64}$/i).or(z.literal("")).default(""),contentFingerprint:z.string().max(160).default(""),sourceProvenance:evidenceSourceProvenanceSchema.nullable().default(null),status:z.enum(["COLLECTED","VERIFIED","DIVERGENT","FAILED"]),evidenceStrength:z.enum(["STRONG","MEDIUM","WEAK"]),notes:z.string().trim().max(3000).default(""),idempotencyKey:z.string().trim().min(8).max(200)}).strict();
export async function recordOfficialEvidence(input:z.input<typeof officialEvidenceInput>&{organizationId:string},client:Client=db){
 const data=officialEvidenceInput.parse((( { organizationId:_organizationId, ...fields } )=>fields)(input));if(!isOfficialUrl(data.sourceUrl))throw new Error("OFFICIAL_SOURCE_URL_REQUIRED");if(data.downloadUrl&&!isOfficialUrl(data.downloadUrl))throw new Error("OFFICIAL_DOWNLOAD_URL_REQUIRED");if(data.status==="VERIFIED"&&!data.documentIdentifier.trim()&&!data.reference.trim())throw new Error("INDIVIDUAL_DOCUMENT_IDENTIFIER_REQUIRED");const operation=await getOperation(data.operationId,client,input.organizationId);if(!operation)throw new Error("EVIDENCE_OPERATION_TENANT_MISMATCH");await initializeAutonomousAcquisition(client);const id=crypto.randomUUID(),collectedAt=new Date().toISOString();
 await client.execute({sql:"INSERT OR IGNORE INTO official_evidence_documents(id,organization_id,operation_id,document_type,title,source,source_url,download_url,document_identifier,reference,published_at,collected_at,page,hash,content_fingerprint,status,evidence_strength,notes,idempotency_key,source_provenance_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",args:[id,input.organizationId,data.operationId,data.documentType,data.title,data.source,data.sourceUrl,data.downloadUrl,data.documentIdentifier,data.reference,data.publishedAt,collectedAt,data.page,data.hash,data.contentFingerprint,data.status,data.evidenceStrength,data.notes,data.idempotencyKey,JSON.stringify(data.sourceProvenance)]});
 const row=await client.execute({sql:"SELECT * FROM official_evidence_documents WHERE organization_id=? AND operation_id=? AND idempotency_key=?",args:[input.organizationId,data.operationId,data.idempotencyKey]});return rowOfficialEvidence(row.rows[0]);
}
export async function listOfficialEvidence(operationId:string,organizationId:string,client:Client=db){await initializeAutonomousAcquisition(client);const rows=await client.execute({sql:"SELECT * FROM official_evidence_documents WHERE operation_id=? AND organization_id=? ORDER BY collected_at DESC",args:[operationId,organizationId]});return rows.rows.map(rowOfficialEvidence)}
const contactInput=z.object({operationId:z.string().uuid(),type:z.enum(["PHONE","MOBILE","EMAIL","WEBSITE","OTHER"]),value:z.string().trim().min(1).max(320),source:z.string().trim().min(1).max(160),sourceUrl:z.string().url().max(1000),confidence:z.number().min(0).max(100),notes:z.string().trim().max(1000).default(""),idempotencyKey:z.string().trim().min(8).max(200)}).strict();
export async function recordAcquisitionContact(input:z.input<typeof contactInput>&{organizationId:string},client:Client=db){const data=contactInput.parse((( { organizationId:_organizationId, ...fields } )=>fields)(input));if(!isOfficialUrl(data.sourceUrl))throw new Error("CONTACT_SOURCE_URL_REQUIRED");if(!await getOperation(data.operationId,client,input.organizationId))throw new Error("CONTACT_OPERATION_TENANT_MISMATCH");await initializeAutonomousAcquisition(client);const id=crypto.randomUUID(),collectedAt=new Date().toISOString();await client.execute({sql:"INSERT OR IGNORE INTO acquisition_contacts VALUES(?,?,?,?,?,?,?,?,?,?,?)",args:[id,input.organizationId,data.operationId,data.type,data.value,data.source,data.sourceUrl,collectedAt,data.confidence,data.notes,data.idempotencyKey]});const row=await client.execute({sql:"SELECT * FROM acquisition_contacts WHERE organization_id=? AND operation_id=? AND idempotency_key=?",args:[input.organizationId,data.operationId,data.idempotencyKey]});return rowContact(row.rows[0])}
export async function listAcquisitionContacts(operationId:string,organizationId:string,client:Client=db){await initializeAutonomousAcquisition(client);const rows=await client.execute({sql:"SELECT * FROM acquisition_contacts WHERE operation_id=? AND organization_id=? ORDER BY collected_at DESC",args:[operationId,organizationId]});return rows.rows.map(rowContact)}
