async function getOfficialCount(operationId:string,organizationId:string,client:Client){const rows=await client.execute({sql:"SELECT * FROM official_evidence_documents WHERE operation_id=? AND organization_id=?",args:[operationId,organizationId]});return rows.rows.map(rowOfficialEvidence)}
