export async function processAcquisitionCycle(input:{organizationId:string;actorUserId:string;workerId?:string;limit?:number;client?:Client;fetcher?:typeof fetch}){const client=input.client||db,limit=Math.min(50,Math.max(1,input.limit||10)),workerId=input.workerId||`interactive-${input.actorUserId}`,counts:Record<string,number>={},errors:string[]=[];await initializeAutonomousAcquisition(client);for(let index=0;index<limit;index++){const job=await claimNext(input.organizationId,workerId,client);if(!job)break;try{const state=await processClaimed(job,client,input.fetcher||fetch);counts[state]=(counts[state]||0)+1}catch(error){const reason=error instanceof Error?error.message:"UNKNOWN_ERROR";errors.push(reason.slice(0,200));const next=nextRetry(job.attempts);await setJob(job,{status:"ERROR",currentStep:"ERROR",finishedAt:new Date().toISOString(),nextRunAt:job.attempts>=job.maxAttempts?"":next,durationMs:Date.now()-Date.parse(job.startedAt||job.updatedAt),lastError:reason.slice(0,500),reasons:["UNKNOWN_ERROR"]},client);await addEvent({organizationId:job.organizationId,operationId:job.operationId,jobId:job.id,sourceId:"worker",eventType:"CASE_ERROR",status:"ERROR",accessResult:"WORKER_ERROR",failureReason:reason.slice(0,300),details:{attempt:job.attempts,maxAttempts:job.maxAttempts},idempotencyKey:`error-${job.attempts}`},client)}}return{processed:Object.values(counts).reduce((sum,count)=>sum+count,0)+errors.length,counts,errors:errors.length,workerId}}

